declare expected jsonb := $original$[{"id": "0ecce32f-332d-4995-b27c-b2d9413917df", "topic": "Addition, subtraction and number problems", "question_text": "A water meter shows 4,080 L, then 4,650 L after rain. Another 375 L is used. Relative to the initial reading, what is the final difference?", "option_a": "195 L below the initial reading", "option_b": "375 L below the initial reading", "option_c": "195 L above the initial reading", "option_d": "570 L above the initial reading", "correct_answer": "C", "explanation": "4,650 - 375 = 4,275; 4,275 - 4,080 = 195 L, so the final reading is greater."}, {"id": "2082ae44-a13b-4934-aaf4-0ffd8f3043e9", "topic": "Addition, subtraction and number problems", "question_text": "A number line has jumps from 5,625 to 5,900 and then to 6,000. Which answer gives both jump sizes and the total change?", "option_a": "325 then 100; total 425", "option_b": "250 then 100; total 350", "option_c": "275 then 100; total 375", "option_d": "275 then 200; total 475", "correct_answer": "C", "explanation": "5,900 - 5,625 = 275; 6,000 - 5,900 = 100. The total increase is 275 + 100 = 375."}, {"id": "2110d7a5-999c-4001-8c67-7647a2d8d142", "topic": "Addition, subtraction and number problems", "question_text": "A receipt lists £12.85, £7.40 and £9.75, with a printed total of £30.00. Which check is correct?", "option_a": "No; they total £30.50", "option_b": "Yes; the three prices total £30.00", "option_c": "No; they total £31.00", "option_d": "No; they total £29.00", "correct_answer": "B", "explanation": "£12.85 + £7.40 = £20.25; adding £9.75 gives £30.00."}, {"id": "2430486c-13d9-40f6-acb6-eb852df9adee", "topic": "Addition, subtraction and number problems", "question_text": "Estimate 4,187 + 3,692 after rounding both numbers to the nearest thousand. Which result is correct?", "option_a": "About 8,000", "option_b": "About 7,000", "option_c": "About 9,000", "option_d": "About 6,000", "correct_answer": "A", "explanation": "4,187 rounds to 4,000 and 3,692 rounds to 4,000."}, {"id": "3896f7c3-a877-4e91-b87c-1ec977383c8c", "topic": "Addition, subtraction and number problems", "question_text": "Find the missing digit: 2,4□8 + 1,375 = 3,823.", "option_a": "5", "option_b": "4", "option_c": "6", "option_d": "3", "correct_answer": "B", "explanation": "Subtract to check: 3,823 - 1,375 = 2,448. The missing tens digit is 4."}, {"id": "60128637-826e-4863-bd8d-44f88b818dbf", "topic": "Addition, subtraction and number problems", "question_text": "Three school houses collect 985, 1,078 and 937 points. Their target is 3,200 points. How many more points are needed?", "option_a": "100 points", "option_b": "400 points", "option_c": "200 points", "option_d": "300 points", "correct_answer": "C", "explanation": "Their total is 3,000; 3,200 − 3,000 = 200."}, {"id": "7c403cd2-f5b8-4352-be1a-03ace25f184b", "topic": "Addition, subtraction and number problems", "question_text": "A bookshop starts with 1,250 books, receives 375 and sells 468. How many remain?", "option_a": "1,157 books", "option_b": "1,093 books", "option_c": "1,625 books", "option_d": "1,718 books", "correct_answer": "A", "explanation": "1,250 + 375 = 1,625, then 1,625 − 468 = 1,157."}, {"id": "8f969f0c-0826-4a23-a9a2-ae37aef82525", "topic": "Addition, subtraction and number problems", "question_text": "In the illustrated number pyramid, each box equals the sum of the two boxes immediately below. Bottom row: 245, 380 and 125. What is the top number?", "option_a": "1,255", "option_b": "1,005", "option_c": "750", "option_d": "1,130", "correct_answer": "D", "explanation": "Middle row: 245 + 380 = 625; 380 + 125 = 505. The top is 625 + 505 = 1,130."}, {"id": "a4674573-06ed-480c-8efe-3bd6d734aa61", "topic": "Addition, subtraction and number problems", "question_text": "A charity hopes to raise £5,000. It has collected £3,685. How much more is needed?", "option_a": "£2,315", "option_b": "£1,685", "option_c": "£1,415", "option_d": "£1,315", "correct_answer": "D", "explanation": "5,000 − 3,685 = 1,315."}, {"id": "b40fcb05-e8d0-4663-9f00-5fa045a91919", "topic": "Addition, subtraction and number problems", "question_text": "A pupil writes 4,600 − 1,999 = 2,599. Which correction and explanation are right?", "option_a": "2,600; subtract 2,000 only", "option_b": "2,601; subtracting 1,999 is subtracting 2,000 then adding 1", "option_c": "2,602; subtract 2,000 then add 2", "option_d": "2,599; subtract 2,000 then take away 1 more", "correct_answer": "B", "explanation": "Subtract 2,000 from 4,600 to get 2,600; because 1,999 is one less than 2,000, add 1 to get 2,601."}, {"id": "058134d7-5621-4c69-ad44-807d98bb39fe", "topic": "Chance, investigation and mixed reasoning", "question_text": "A fair spinner has four equal sectors. It must show A with probability 1/2, while B and C are equally likely. Which set of labels works?", "option_a": "A, B, B, C", "option_b": "A, B, C, C", "option_c": "A, A, B, C", "option_d": "A, A, A, B", "correct_answer": "C", "explanation": "Two of four equally likely parts must show A. The other two parts split equally between B and C."}, {"id": "13cd0c17-9c1e-4ede-a21f-45851f4cb178", "topic": "Chance, investigation and mixed reasoning", "question_text": "There are only yellow counters in a bag. Which chance word describes selecting yellow?", "option_a": "Equally likely", "option_b": "Impossible", "option_c": "Possible but not certain", "option_d": "Certain", "correct_answer": "D", "explanation": "Every counter is yellow."}, {"id": "2c6d60c1-2ccb-48c6-9eb6-402652461e19", "topic": "Chance, investigation and mixed reasoning", "question_text": "Twenty-four pupils each choose exactly one club. One third choose art, one quarter choose music, and the rest choose sport. How many choose sport?", "option_a": "10 learners", "option_b": "8 learners", "option_c": "12 learners", "option_d": "14 learners", "correct_answer": "A", "explanation": "Art = 8; music = 6; sport = 24 − 8 − 6 = 10."}, {"id": "578adc7e-9410-4eb9-bfeb-7b494ec7b9ed", "topic": "Chance, investigation and mixed reasoning", "question_text": "A fair spinner has six equal sectors labelled 1,1,2,2,2,3. Which result is most likely?", "option_a": "All are equally likely", "option_b": "3", "option_c": "1", "option_d": "2", "correct_answer": "D", "explanation": "Three of the six equally sized sections show 2."}, {"id": "71cfe402-46d8-437e-b659-783e908d1878", "topic": "Chance, investigation and mixed reasoning", "question_text": "Two fair dice are thrown and the results added. Is an even total guaranteed? Which pair of examples supports your answer?", "option_a": "No; 2 + 4 is even, but 1 + 2 is odd", "option_b": "Yes; all sums of two dice are even", "option_c": "No; all sums are odd", "option_d": "Yes; 1 + 2 is even", "correct_answer": "A", "explanation": "The sum depends on the two faces. Different parity combinations can make even or odd totals."}, {"id": "9b17bf33-bc6c-46e2-acf1-7d4e48e9fba0", "topic": "Chance, investigation and mixed reasoning", "question_text": "Which pair contains ONLY outcomes that are possible from a spinner labelled 2, 4, 6 and 8?", "option_a": "1 and 5", "option_b": "9 and 10", "option_c": "2 and 8", "option_d": "3 and 7", "correct_answer": "C", "explanation": "Only these four numbers appear on the spinner."}, {"id": "abcaed71-db3a-491b-bb76-ed39444c6ecd", "topic": "Chance, investigation and mixed reasoning", "question_text": "Which plan provides a fair test of which of two paper aeroplanes travels farther?", "option_a": "Give one a push and throw the other gently", "option_b": "Launch both from the same line with the same thrower, repeating trials", "option_c": "Test one once and assume the result is final", "option_d": "Launch one indoors and one outdoors", "correct_answer": "B", "explanation": "Control starting point and launch method; repeat measurements for reliability."}, {"id": "c91d758b-71db-4f05-89dc-38f04989f4df", "topic": "Chance, investigation and mixed reasoning", "question_text": "A spinner has four equal sectors labelled R, B, R, G. What fraction of spins should land on R in a fair model?", "option_a": "1/2", "option_b": "1/4", "option_c": "3/4", "option_d": "1/3", "correct_answer": "A", "explanation": "Two of the four equal sectors have R, so 2/4 = 1/2."}, {"id": "dd1ab92b-ce69-4545-9cbc-ddfc87d2756c", "topic": "Chance, investigation and mixed reasoning", "question_text": "A box has five red, five green and two blue counters. Which colours have equal probability?", "option_a": "Red and blue", "option_b": "Red and green", "option_c": "All three colours", "option_d": "Green and blue", "correct_answer": "B", "explanation": "They each appear five times in the same box; blue appears only twice."}, {"id": "e3ad45b7-4db8-49b0-9deb-02903bfe9b06", "topic": "Chance, investigation and mixed reasoning", "question_text": "A fair spinner has 3 red, 3 blue and 2 green sectors. Which probability statement is correct?", "option_a": "Green is more likely than either red or blue", "option_b": "Red and blue are impossible; green is certain", "option_c": "Red is more likely than blue; green is impossible", "option_d": "Red and blue are equally likely; green is possible", "correct_answer": "D", "explanation": "Red and blue each occupy 3/8; green occupies 2/8."}, {"id": "15c86bf1-df77-46a0-862a-c925d341d80d", "topic": "Fractions and decimals", "question_text": "Which is greater, 0.6 or 0.45?", "option_a": "They are equal", "option_b": "0.6", "option_c": "0.45 because 45 is larger than 6", "option_d": "0.45", "correct_answer": "B", "explanation": "0.60 is larger than 0.45."}, {"id": "521c731d-bb73-4078-abec-9d89bc3a12e7", "topic": "Fractions and decimals", "question_text": "The two fraction strips show 4/8 and 2/4. Which answer correctly compares them?", "option_a": "No; 2/4 is larger because its pieces are bigger", "option_b": "Yes; both shaded regions represent one half", "option_c": "Yes; both equal one quarter", "option_d": "No; 4/8 is larger because 4 is greater than 2", "correct_answer": "B", "explanation": "4/8 = 1/2 and 2/4 = 1/2. Half of each equally divided whole is shaded."}, {"id": "54d5d725-d62a-4e87-aae5-0d77cc34dec2", "topic": "Fractions and decimals", "question_text": "Which ordering and explanation are correct for 0.28, 0.30 and 0.34?", "option_a": "0.30 < 0.28 < 0.34", "option_b": "0.28 < 0.30 < 0.34; 0.30 is between the others", "option_c": "0.28 < 0.34 < 0.30", "option_d": "0.34 < 0.30 < 0.28", "correct_answer": "B", "explanation": "28 hundredths is less than 30 hundredths, which is less than 34 hundredths."}, {"id": "82e7bd3c-d156-419d-9218-97d6230a8071", "topic": "Fractions and decimals", "question_text": "The diagram shows 4 of 6 equal parts shaded. Which equivalent fraction has a denominator of 3?", "option_a": "3/4", "option_b": "1/3", "option_c": "4/3", "option_d": "2/3", "correct_answer": "D", "explanation": "4/6 simplifies by dividing top and bottom by 2."}, {"id": "866db715-f30f-4c70-8e79-4fe54ae4cdc0", "topic": "Fractions and decimals", "question_text": "Complete: 1/2 = ___/8.", "option_a": "2", "option_b": "8", "option_c": "4", "option_d": "6", "correct_answer": "C", "explanation": "Multiply numerator and denominator of 1/2 by 4."}, {"id": "92490843-702c-49d9-b0da-60d762674ba5", "topic": "Fractions and decimals", "question_text": "The diagram shows 6 of 8 equal parts shaded. Which is the simplest fraction?", "option_a": "3/4", "option_b": "6/4", "option_c": "2/3", "option_d": "3/8", "correct_answer": "A", "explanation": "6/8 simplifies to 3/4 after dividing both the numerator and denominator by 2."}, {"id": "cbf23773-c71c-4cc5-92db-004cec671bcc", "topic": "Fractions and decimals", "question_text": "Which missing numerators complete 2.34 = 2 + □/10 + □/100?", "option_a": "4 tenths and 3 hundredths", "option_b": "3 tenths and 40 hundredths", "option_c": "3 tenths and 4 hundredths", "option_d": "2 tenths and 34 hundredths", "correct_answer": "C", "explanation": "2.34 has 2 ones, 3 tenths and 4 hundredths."}, {"id": "dc4964f2-b3cc-4e8a-a9ae-ed6083971fa0", "topic": "Fractions and decimals", "question_text": "The fraction strip has ten equal parts and seven shaded parts. Which fraction–decimal pair represents the shaded amount?", "option_a": "7/100 and 0.07", "option_b": "7/10 and 0.7", "option_c": "7/10 and 7.0", "option_d": "3/10 and 0.3", "correct_answer": "B", "explanation": "Seven tenths can be written as 7/10 or 0.7."}, {"id": "dc7c0843-d016-46f9-9d95-a6702dc755b9", "topic": "Fractions and decimals", "question_text": "Of 32 pupils, 1/4 join choir and 3/8 join athletics. Nobody joins both. How many join neither?", "option_a": "12 pupils", "option_b": "8 pupils", "option_c": "20 pupils", "option_d": "16 pupils", "correct_answer": "A", "explanation": "Choir 8; athletics 12; 32 − 8 − 12 = 12."}, {"id": "f6a04dbb-9851-412c-b5f3-f3c76ec6b49b", "topic": "Fractions and decimals", "question_text": "A ribbon is 2 m long. Kofi uses three quarters of it. How many centimetres remain?", "option_a": "75 cm", "option_b": "125 cm", "option_c": "50 cm", "option_d": "150 cm", "correct_answer": "C", "explanation": "One quarter of 2 m remains: 0.5 m = 50 cm."}, {"id": "2c60a2fe-972d-4042-93f9-34aeece820d3", "topic": "Geometry, symmetry and position", "question_text": "On the grid, reflect row 2, column 2 in the vertical mirror line. In which column will the reflected square appear?", "option_a": "Column 3", "option_b": "Column 5", "option_c": "Column 6", "option_d": "Column 4", "correct_answer": "B", "explanation": "In a 6-column grid, column 2 mirrors to column 5."}, {"id": "3d95c34e-7eca-4e34-8b47-9195a2b2f95e", "topic": "Geometry, symmetry and position", "question_text": "Three corners of a rectangle are (1,2), (1,6) and (5,6). What is the missing corner?", "option_a": "(1,5)", "option_b": "(6,1)", "option_c": "(2,5)", "option_d": "(5,2)", "correct_answer": "D", "explanation": "Use matching x- and y-coordinates for horizontal and vertical sides."}, {"id": "5887fe77-133b-4844-9889-b879a5e1e65e", "topic": "Geometry, symmetry and position", "question_text": "A quadrilateral has exactly one pair of parallel sides. Which name fits best: parallelogram, trapezium or square?", "option_a": "Rhombus", "option_b": "Square", "option_c": "Parallelogram", "option_d": "Trapezium", "correct_answer": "D", "explanation": "A trapezium (UK convention) has one pair of parallel sides; squares and parallelograms have two."}, {"id": "62f5e3b3-f62e-4b1e-9897-b7cdaac7db20", "topic": "Geometry, symmetry and position", "question_text": "A route on the grid goes from A(2,1) to B(6,1), then to C(6,4). How many grid units is the route altogether?", "option_a": "7 grid units", "option_b": "4 grid units", "option_c": "5 grid units", "option_d": "11 grid units", "correct_answer": "A", "explanation": "It travels 4 units right and then 3 up. Total = 4 + 3 = 7 units."}, {"id": "832ce7fc-9715-4410-b897-76990dd3ccb0", "topic": "Geometry, symmetry and position", "question_text": "Which list orders 45°, 120°, 90° and 30° from smallest to largest?", "option_a": "30°, 90°, 45°, 120°", "option_b": "120°, 90°, 45°, 30°", "option_c": "45°, 30°, 90°, 120°", "option_d": "30°, 45°, 90°, 120°", "correct_answer": "D", "explanation": "Compare the number of degrees."}, {"id": "96558e61-f039-47af-b0e3-c4d13bbbbbde", "topic": "Geometry, symmetry and position", "question_text": "The figure shows angles A, B and C. Angle B is a right angle. Which classification of A and C is correct?", "option_a": "A is acute and C is obtuse", "option_b": "A is obtuse and C is acute", "option_c": "Both A and C are acute", "option_d": "Both A and C are right angles", "correct_answer": "A", "explanation": "Angle A is smaller than 90 degrees. C is larger than 90 degrees; B is exactly 90 degrees."}, {"id": "cd51832a-3e1a-4ae9-8f16-8dd282c70535", "topic": "Geometry, symmetry and position", "question_text": "A compass arrow points east, then makes three quarter-turns clockwise. Which direction is it pointing?", "option_a": "South", "option_b": "West", "option_c": "North", "option_d": "East", "correct_answer": "C", "explanation": "East -> South -> West -> North after three clockwise quarter-turns."}, {"id": "d9dae4ce-9b6b-492d-98fb-75808bd45b36", "topic": "Geometry, symmetry and position", "question_text": "A learner says: 'Every square is a rectangle, but not every rectangle is a square.' Which statement judges this correctly?", "option_a": "False; squares cannot be rectangles", "option_b": "True; a rectangle does not have right angles", "option_c": "True; squares satisfy all rectangle properties, but some rectangles have unequal adjacent sides", "option_d": "False; every rectangle must have four equal sides", "correct_answer": "C", "explanation": "A square has four right angles like a rectangle, but also has four equal sides."}, {"id": "f4dfd352-f32e-49c1-8c29-763acef1783a", "topic": "Geometry, symmetry and position", "question_text": "A quadrilateral has four equal sides, no right angles, and both pairs of opposite sides parallel. Which name and reason fit?", "option_a": "Rhombus; four equal sides and opposite sides parallel", "option_b": "Square; all four angles must be right angles", "option_c": "Trapezium; it has exactly one pair of parallel sides", "option_d": "Rectangle; all four sides must be unequal", "correct_answer": "A", "explanation": "A rhombus has four equal sides and opposite sides parallel; it need not have right angles."}, {"id": "f55c9336-af36-491a-82ac-da25fea618f6", "topic": "Geometry, symmetry and position", "question_text": "How many lines of symmetry does a rectangle that is not a square have?", "option_a": "4 lines", "option_b": "2 lines", "option_c": "0 lines", "option_d": "1 line", "correct_answer": "B", "explanation": "It has one vertical and one horizontal line of symmetry."}, {"id": "0bf89c27-d393-4a47-9c21-4ff11cfbae08", "topic": "Measurement, area and perimeter", "question_text": "Using the shaded rectangle shown on the grid of 1 cm squares, what is its area?", "option_a": "48 cm²", "option_b": "12 cm²", "option_c": "22 cm²", "option_d": "24 cm²", "correct_answer": "D", "explanation": "The rectangle has 4 rows and 6 columns of 1 cm² tiles."}, {"id": "1edb193f-7c88-43b5-8883-e47b726780be", "topic": "Measurement, area and perimeter", "question_text": "An 8 cm by 5 cm rectangle is covered with 1 cm² tiles without gaps or overlaps. How many tiles are needed?", "option_a": "26 tiles", "option_b": "80 tiles", "option_c": "40 tiles", "option_d": "13 tiles", "correct_answer": "C", "explanation": "There are 8 columns and 5 rows, so 8 x 5 = 40 square centimetres."}, {"id": "37cd144c-729d-46fc-8a9d-79d47d1e2445", "topic": "Measurement, area and perimeter", "question_text": "A rectangular garden is 12 m long and 5 m wide. Which answer gives its area and perimeter with correct units?", "option_a": "Area 34 m² and perimeter 60 m", "option_b": "Area 17 m² and perimeter 60 m", "option_c": "Area 60 m² and perimeter 34 m", "option_d": "Area 60 m and perimeter 34 m²", "correct_answer": "C", "explanation": "Area is 12 × 5; perimeter is 2 × (12 + 5)."}, {"id": "4163c672-ab73-46df-9684-c16b5227f398", "topic": "Measurement, area and perimeter", "question_text": "Which order shows 850 g, 1 kg and 1,250 g from lightest to heaviest?", "option_a": "850 g, 1,250 g, 1 kg", "option_b": "850 g, 1 kg, 1,250 g", "option_c": "1,250 g, 1 kg, 850 g", "option_d": "1 kg, 850 g, 1,250 g", "correct_answer": "B", "explanation": "1 kg = 1,000 g."}, {"id": "6b68e4f5-08d2-4881-aacf-013a2393d18b", "topic": "Measurement, area and perimeter", "question_text": "A pencil is 18.4 cm long. Amina estimated 17 cm, Babu 19 cm and Chen 20 cm. Who was closest, and by how much?", "option_a": "Babu; his estimate is 1.4 cm away", "option_b": "Chen; his estimate is 1.6 cm away", "option_c": "Amina; her estimate is 1.4 cm away", "option_d": "Babu; his estimate is 0.6 cm away", "correct_answer": "D", "explanation": "Differences are 1.4 cm, 0.6 cm and 1.6 cm."}, {"id": "83b1de92-4d0e-4539-a0ca-2e6662a02c5b", "topic": "Measurement, area and perimeter", "question_text": "Which measurement is longer—2 km 50 m or 2,450 m—and by how much?", "option_a": "2,450 m, by 400 m", "option_b": "2 km 50 m, by 400 m", "option_c": "2,450 m, by 50 m", "option_d": "2 km 50 m, by 950 m", "correct_answer": "A", "explanation": "2 km 50 m = 2,050 m; 2,450 − 2,050 = 400 m."}, {"id": "8ab207c7-4628-40aa-af27-711d522157cd", "topic": "Measurement, area and perimeter", "question_text": "What does 2,500 mL equal in litres and millilitres?", "option_a": "2 L 500 mL", "option_b": "25 L", "option_c": "2 L 50 mL", "option_d": "250 L", "correct_answer": "A", "explanation": "1,000 mL makes 1 litre."}, {"id": "a9b0a1a6-4d41-48ce-a3f7-68f3b3a1a7b8", "topic": "Measurement, area and perimeter", "question_text": "3 km = ___ m.", "option_a": "3 m", "option_b": "30,000 m", "option_c": "300 m", "option_d": "3,000 m", "correct_answer": "D", "explanation": "1 km = 1,000 m, so 3 km = 3,000 m."}, {"id": "bb9ab316-b5ee-4573-917f-6d780225316e", "topic": "Measurement, area and perimeter", "question_text": "A route is 1 km 250 m, then 780 m, then 990 m. Which statement about the total is correct?", "option_a": "Yes; the total is 3 km 200 m", "option_b": "Yes; 3 km 20 m in total, exceeding 3 km by 20 m", "option_c": "No; the total is exactly 3 km", "option_d": "No; the total is 2 km 920 m", "correct_answer": "B", "explanation": "1,250 + 780 + 990 = 3,020 m, which is 20 m more than 3 km."}, {"id": "bfef4084-9d5b-4111-88ce-62405a8d471d", "topic": "Measurement, area and perimeter", "question_text": "A 5 m rope is cut into six 65 cm pieces. How many centimetres remain?", "option_a": "110 cm", "option_b": "390 cm", "option_c": "65 cm", "option_d": "210 cm", "correct_answer": "A", "explanation": "500 − (6 × 65) = 500 − 390 = 110 cm."}, {"id": "6797b65d-5860-42ab-a675-537765b6a988", "topic": "Multiplication and division", "question_text": "Which values complete BOTH calculations: 9 × □ = 72 and 72 ÷ □ = 9?", "option_a": "8 then 9", "option_b": "7 in both boxes", "option_c": "9 in both boxes", "option_d": "8 in both boxes", "correct_answer": "D", "explanation": "9 x 8 = 72 and 72 ÷ 8 = 9. Multiplication and division undo one another."}, {"id": "67c99de3-c6e5-45f4-861f-0d6230371682", "topic": "Multiplication and division", "question_text": "Which number fills the blank: 6 × (10 + 4) = (6 × 10) + (6 × □)?", "option_a": "10", "option_b": "4", "option_c": "14", "option_d": "3", "correct_answer": "B", "explanation": "Partition 14 into 10 and 4. Both expressions represent 6 x 14."}, {"id": "74972318-a2aa-4f79-9067-b566cb5267e2", "topic": "Multiplication and division", "question_text": "The diagram shows an array with 28 counters in 4 rows of 7. Which different rectangular array also uses exactly 28 counters?", "option_a": "3 rows of 9 counters", "option_b": "6 rows of 5 counters", "option_c": "2 rows of 14 counters", "option_d": "5 rows of 6 counters", "correct_answer": "C", "explanation": "Any distinct factor pair of 28 is valid, for example 2 x 14 = 28."}, {"id": "7dd84c25-f1de-49a1-879a-1806dc5fc48e", "topic": "Multiplication and division", "question_text": "What is 23 × 6 using 20 × 6 plus 3 × 6?", "option_a": "146", "option_b": "136", "option_c": "126", "option_d": "138", "correct_answer": "D", "explanation": "20 × 6 = 120 and 3 × 6 = 18; add to make 138."}, {"id": "890ccf87-585b-454f-a377-0da869e50096", "topic": "Multiplication and division", "question_text": "A frog makes equal jumps of 7 from 0 to 70. How many jumps are needed?", "option_a": "10 jumps", "option_b": "9 jumps", "option_c": "8 jumps", "option_d": "11 jumps", "correct_answer": "A", "explanation": "Count 0, 7, 14, ..., 70. The count is 70 ÷ 7 = 10."}, {"id": "9242a91d-d8bc-43dc-937c-a5d5a38e5058", "topic": "Multiplication and division", "question_text": "A shop receives 18 packets of 6 pencils and another 12 packets of 6. Which efficient calculation gives the total?", "option_a": "(18 + 12) × 6 = 180 pencils", "option_b": "(18 × 12) + 6 = 222 pencils", "option_c": "(18 + 6) × 12 = 288 pencils", "option_d": "18 + 12 + 6 = 36 pencils", "correct_answer": "A", "explanation": "Add packets first: (18 + 12) x 6 = 30 x 6 = 180."}, {"id": "94eeaf12-7b0b-4248-8b0d-dacddf915d63", "topic": "Multiplication and division", "question_text": "Four clubs have 18 members each. Members from different clubs must not be mixed. How many teams of 6 can be made altogether?", "option_a": "24 teams; 6 from each club", "option_b": "18 teams; 6 from three clubs", "option_c": "9 teams; 3 from three clubs", "option_d": "12 teams; 3 from each club", "correct_answer": "D", "explanation": "18 ÷ 6 = 3 teams per club; 4 x 3 = 12. Or 4 x 18 = 72 then 72 ÷ 6 = 12."}, {"id": "bbf88ec0-51a0-49ec-bad8-1f5dce446f1a", "topic": "Multiplication and division", "question_text": "A baker packs 96 buns equally into 8 boxes. How many buns go in each box?", "option_a": "12 buns", "option_b": "11 buns", "option_c": "14 buns", "option_d": "16 buns", "correct_answer": "A", "explanation": "96 ÷ 8 = 12."}, {"id": "d698a79b-fc25-40ef-8bc9-6ccf4a5d2919", "topic": "Multiplication and division", "question_text": "Six classes have 27 pupils each. Eighteen pupils are absent on sports day. How many attend?", "option_a": "162 pupils", "option_b": "152 pupils", "option_c": "144 pupils", "option_d": "126 pupils", "correct_answer": "C", "explanation": "6 × 27 = 162; 162 − 18 = 144."}, {"id": "fa23426a-3596-4343-b712-b5a6b0af66a1", "topic": "Multiplication and division", "question_text": "59 children travel in minibuses that hold 8 children each. How many FULL minibuses and how many children are left over?", "option_a": "7 full minibuses and 5 children left over", "option_b": "7 full minibuses and 3 children left over", "option_c": "6 full minibuses and 11 children left over", "option_d": "8 full minibuses and 3 children left over", "correct_answer": "B", "explanation": "7 × 8 = 56 and 59 − 56 = 3."}, {"id": "00118b6f-d2aa-45e3-a7a2-49b19229641c", "topic": "Patterns, factors and multiples", "question_text": "Which number breaks the pattern of multiples of 8: 16, 24, 32, 39, 48?", "option_a": "48", "option_b": "32", "option_c": "16", "option_d": "39", "correct_answer": "D", "explanation": "The other numbers equal 8 x 2, 8 x 3, 8 x 4 and 8 x 6. 39 is not divisible by 8."}, {"id": "06d086b0-d5b2-4d89-b9ae-1ea126c204c1", "topic": "Patterns, factors and multiples", "question_text": "Ella says that every multiple of 10 is a multiple of 5. Which response is mathematically correct?", "option_a": "Yes; every multiple of 10 is 2 times a multiple of 5", "option_b": "No; 20 is not a multiple of 5", "option_c": "Yes; only 10 itself is a multiple of 5", "option_d": "No; 50 is a multiple of 10 but not of 5", "correct_answer": "A", "explanation": "Every multiple of 10 equals 10n = 5 × (2n), so it is divisible by 5."}, {"id": "0fbc8e59-02a5-4545-8db6-801f3fc72e31", "topic": "Patterns, factors and multiples", "question_text": "Which numbers in this list are multiples of 9: 18, 23, 36, 40, 54?", "option_a": "18, 23 and 36", "option_b": "All five numbers", "option_c": "18, 36 and 54", "option_d": "23, 40 and 54", "correct_answer": "C", "explanation": "These are 9 × 2, 9 × 4 and 9 × 6."}, {"id": "1aae48ad-ee54-46ec-a339-b12682d627f8", "topic": "Patterns, factors and multiples", "question_text": "A number machine doubles each input and subtracts 3. Which list gives the outputs for inputs 4, 7 and 9, with the correct rule?", "option_a": "5, 10, 15; multiply by 5", "option_b": "11, 17, 21; multiply by 2 then add 3", "option_c": "8, 14, 18; add 4", "option_d": "5, 11, 15; multiply by 2 then subtract 3", "correct_answer": "D", "explanation": "2 x 4 - 3 = 5; 2 x 7 - 3 = 11; 2 x 9 - 3 = 15."}, {"id": "64a0135f-f98e-4d42-9430-0c8e411ca4d0", "topic": "Patterns, factors and multiples", "question_text": "A lift starts on floor 2. Its pattern repeats: up 7 floors, down 3 floors. On which floor will it stop after two complete repeats?", "option_a": "Floor 18", "option_b": "Floor 16", "option_c": "Floor 6", "option_d": "Floor 10", "correct_answer": "D", "explanation": "Each repeat increases the floor number by 4. Starting at 2: 2 + 4 + 4 = 10."}, {"id": "735bfbda-af5a-4a64-8c46-8c63e8a3fdac", "topic": "Patterns, factors and multiples", "question_text": "Which pair of numbers has a product of 30?", "option_a": "3 and 10", "option_b": "4 and 6", "option_c": "5 and 8", "option_d": "2 and 12", "correct_answer": "A", "explanation": "3 x 10 = 30. The other pairs multiply to 24 and 40."}, {"id": "c7957a97-b550-4780-a820-add624a28518", "topic": "Patterns, factors and multiples", "question_text": "Which is the smallest positive common multiple of 6 and 8?", "option_a": "12", "option_b": "48", "option_c": "24", "option_d": "18", "correct_answer": "C", "explanation": "Multiples of 6 include 6,12,18,24; multiples of 8 include 8,16,24."}, {"id": "cdc3b7cf-1ea0-4273-9389-81774b4f14a3", "topic": "Patterns, factors and multiples", "question_text": "Which choice gives three correct factor pairs of 24?", "option_a": "2×24, 3×8, 6×4", "option_b": "1×24, 2×12, 3×8", "option_c": "1×12, 2×8, 3×6", "option_d": "1×24, 3×12, 4×8", "correct_answer": "B", "explanation": "Factor pairs multiply to give 24."}, {"id": "d991b248-057a-4bc1-b9d1-3c4a5c85fa9f", "topic": "Patterns, factors and multiples", "question_text": "A growing pattern has 5 counters in figure 1, 8 in figure 2 and 11 in figure 3. How many are in figure 6?", "option_a": "18 counters", "option_b": "20 counters", "option_c": "23 counters", "option_d": "17 counters", "correct_answer": "B", "explanation": "Add 3 with each new figure: 5, 8, 11, 14, 17, 20."}, {"id": "eb9ce50c-f9b9-43b1-8d17-c4a0fb49feec", "topic": "Patterns, factors and multiples", "question_text": "The Venn diagram has circles for multiples of 3 and multiples of 5. Where should 30 be placed?", "option_a": "In the overlap of the two circles", "option_b": "In the left circle only", "option_c": "Outside both circles", "option_d": "In the right circle only", "correct_answer": "A", "explanation": "30 is divisible by both 3 and 5, so it belongs in the overlap."}, {"id": "1fbf077d-9643-4070-b04a-83127aee185b", "topic": "Place value, comparison and rounding", "question_text": "On the number line, write the missing number midway between 3,200 and 3,400.", "option_a": "3,250", "option_b": "3,600", "option_c": "3,300", "option_d": "3,350", "correct_answer": "C", "explanation": "The midpoint is 100 more than 3,200 and 100 less than 3,400."}, {"id": "23b7754a-f4fd-4ba5-ad01-996ba3f274b7", "topic": "Place value, comparison and rounding", "question_text": "My thousands digit is 5. My hundreds digit is 2 less than my thousands digit. My tens digit is double the hundreds digit, and my ones digit is 1. Which number am I?", "option_a": "5,361", "option_b": "5,316", "option_c": "5,362", "option_d": "5,261", "correct_answer": "A", "explanation": "Thousands = 5; hundreds = 3; tens = 6; ones = 1."}, {"id": "258a07ee-b3cd-44de-aab4-a0836ca52bd5", "topic": "Place value, comparison and rounding", "question_text": "Four numbers lie near 5,000: 4,895; 5,108; 5,020; 4,970. Which is closest to 5,000?", "option_a": "5,020", "option_b": "4,970", "option_c": "4,895", "option_d": "5,108", "correct_answer": "A", "explanation": "Their distances from 5,000 are 105, 108, 20 and 30. The smallest gap is 20."}, {"id": "67e2b570-25ce-4fd6-a76c-10cb3a381f9e", "topic": "Place value, comparison and rounding", "question_text": "Box labels read 4,207, 4,270 and 4,720. Which number has zero tens?", "option_a": "4,720", "option_b": "4,207", "option_c": "All three labels", "option_d": "4,270", "correct_answer": "B", "explanation": "In 4,207 the tens digit is 0. The other tens digits are 7 and 2."}, {"id": "69f04145-66cc-43d3-82c4-3c6226f8e106", "topic": "Place value, comparison and rounding", "question_text": "Regroup 3 thousands, 12 hundreds, 4 tens and 6 ones as a four-digit number.", "option_a": "3,246", "option_b": "5,246", "option_c": "4,246", "option_d": "4,206", "correct_answer": "C", "explanation": "12 hundreds = 1 thousand and 2 hundreds, so 3,000 + 1,200 + 40 + 6 = 4,246."}, {"id": "80fbf08b-d875-4323-a3d0-29d43a01a558", "topic": "Place value, comparison and rounding", "question_text": "A learner rounds 6,748 to the nearest hundred. Which answer includes the correct reason?", "option_a": "6,800: because 748 is more than 700", "option_b": "6,700: it is nearer 6,700 than 6,800", "option_c": "6,000: because the thousands digit is 6", "option_d": "6,800: because the tens digit is 4", "correct_answer": "B", "explanation": "6,748 is 48 above 6,700 and 52 below 6,800."}, {"id": "abd51459-5c55-4e86-9c86-97cb10b11c1b", "topic": "Place value, comparison and rounding", "question_text": "What is the largest whole number that rounds to 3,600 to the nearest hundred?", "option_a": "3,650", "option_b": "3,599", "option_c": "3,649", "option_d": "3,699", "correct_answer": "C", "explanation": "3,649 rounds down to 3,600; 3,650 rounds up to 3,700."}, {"id": "cc9b5dda-1ff5-45f0-a405-dd82628e3d93", "topic": "Place value, comparison and rounding", "question_text": "A pupil rounds 4,950 to 4,900 to the nearest hundred. Which explanation gives the correct rounding?", "option_a": "4,950; it is already exact", "option_b": "5,000; 4,950 is halfway and rounds up", "option_c": "4,000; ignore the tens digit", "option_d": "4,900; the hundreds digit stays 9", "correct_answer": "B", "explanation": "4,950 is halfway between 4,900 and 5,000; using the usual half-up rule, round to 5,000."}, {"id": "dcd8e27f-3811-497b-99aa-927672c3fdda", "topic": "Place value, comparison and rounding", "question_text": "The digits 8, 0, 4 and 6 must each be used once. Which statement about making an odd number and the greatest even number is correct?", "option_a": "Yes; 8,406 is an odd number", "option_b": "No; 8,604 is the greatest even number", "option_c": "Yes; 8,640 is an odd number", "option_d": "No; 8,640 is the greatest even number", "correct_answer": "D", "explanation": "Every supplied digit is even, so the final digit cannot be odd. Arrange the digits in descending order to make 8,640."}, {"id": "dcee20d2-2539-468e-8741-826b74d3034c", "topic": "Place value, comparison and rounding", "question_text": "Use the place-value chart. Which digit is in the hundreds column?", "option_a": "9", "option_b": "0", "option_c": "7", "option_d": "5", "correct_answer": "D", "explanation": "The chart shows 7 thousands, 5 hundreds, 0 tens and 9 ones."}, {"id": "17e45bd5-bd10-4716-bac5-337a0ffc0111", "topic": "Statistical methods and data", "question_text": "On the temperature line graph, how many degrees Celsius did the temperature rise from 9 a.m. to midday?", "option_a": "9°C", "option_b": "6°C", "option_c": "12°C", "option_d": "3°C", "correct_answer": "B", "explanation": "It rises from 18°C to 24°C."}, {"id": "2db93ffe-8983-4eef-ba50-6010d1e5e93b", "topic": "Statistical methods and data", "question_text": "On one day, 14 pupils walk to school and 7 cycle. Nina predicts twice as many pupils will walk tomorrow. Which judgement is justified by the data?", "option_a": "Yes; walking always doubles from one day to the next", "option_b": "No; a single day's responses do not prove tomorrow's result", "option_c": "No; tomorrow must have exactly 7 walkers", "option_d": "Yes; 14 is twice 7, so tomorrow must match", "correct_answer": "B", "explanation": "The graph reports one day's travel choices; it cannot establish tomorrow's behaviour without further evidence."}, {"id": "4470efa9-77fd-47b3-aeb8-f50d6a3a2211", "topic": "Statistical methods and data", "question_text": "One group of five tally marks and three extra single tally marks represent what frequency?", "option_a": "9", "option_b": "8", "option_c": "6", "option_d": "7", "correct_answer": "B", "explanation": "A diagonal strike through four marks completes a group of five; add three single marks to make eight."}, {"id": "63f625a8-5367-4f64-8b15-785161d4b681", "topic": "Statistical methods and data", "question_text": "The numbers of pets owned by eight pupils are 0,1,2,0,1,1,3,2. How many pupils own at least two pets?", "option_a": "2 pupils", "option_b": "5 pupils", "option_c": "3 pupils", "option_d": "4 pupils", "correct_answer": "C", "explanation": "Two pupils have 2 pets and one has 3."}, {"id": "9b189ac7-038f-4d0f-a838-5ef2c4019f45", "topic": "Statistical methods and data", "question_text": "The Venn diagram has 5 chess-only, 4 draughts-only, 3 who play both and 2 who play neither. Which totals are correct?", "option_a": "12 play at least one; 2 play neither", "option_b": "14 play at least one; 0 play neither", "option_c": "9 play at least one; 5 play neither", "option_d": "8 play at least one; 6 play neither", "correct_answer": "A", "explanation": "Add the three regions inside the circles: 5 + 3 + 4 = 12; two children appear outside."}, {"id": "9cba0edd-6d3a-4b17-82f4-8d7f63b228e0", "topic": "Statistical methods and data", "question_text": "In the Carroll diagram, where should the number 12 be placed?", "option_a": "Even and a multiple of 3", "option_b": "Even and not a multiple of 3", "option_c": "Odd and a multiple of 3", "option_d": "Odd and not a multiple of 3", "correct_answer": "A", "explanation": "12 is divisible by 2 and by 3."}, {"id": "cb9226a3-4fa9-4adc-86f8-b5663daf098a", "topic": "Statistical methods and data", "question_text": "A weekly table gives Monday 12, Tuesday 15, Thursday 11 and Friday 14. The weekly total is 65. What is Wednesday's number?", "option_a": "12", "option_b": "15", "option_c": "13", "option_d": "14", "correct_answer": "C", "explanation": "Known total 12 + 15 + 11 + 14 = 52; 65 − 52 = 13."}, {"id": "d26312ad-4cb1-4d31-b753-e4298a389002", "topic": "Statistical methods and data", "question_text": "A survey records 16 drawing votes, 12 music votes and 9 sport votes. Seven pupils switch from drawing to sport. Which activity now has the most votes?", "option_a": "Drawing (9 votes)", "option_b": "Music (19 votes)", "option_c": "Drawing (16 votes)", "option_d": "Sport (16 votes)", "correct_answer": "D", "explanation": "Drawing becomes 9, music stays 12, and sport becomes 16. Sport now has the most votes."}, {"id": "e1ba5ae8-30c9-4f19-8cac-2cf10c5d4f46", "topic": "Statistical methods and data", "question_text": "A pictogram represents 4 books with a whole symbol and 2 with a half symbol. A row has two whole symbols and one half symbol. How many books?", "option_a": "6 books", "option_b": "12 books", "option_c": "8 books", "option_d": "10 books", "correct_answer": "D", "explanation": "4 + 4 + 2 = 10; a half-symbol is worth half the value of a full symbol."}, {"id": "e9a257bf-bb39-4652-822f-0ec8ef658105", "topic": "Statistical methods and data", "question_text": "Using the library bar chart, which days are busiest and quietest, and what is the difference in the number of books?", "option_a": "Thursday and Monday; difference of 6 books", "option_b": "Friday and Wednesday; difference of 8 books", "option_c": "Thursday and Wednesday; difference of 6 books", "option_d": "Tuesday and Wednesday; difference of 4 books", "correct_answer": "C", "explanation": "The Thursday bar shows 14 books and Wednesday 8, giving a difference of 6."}, {"id": "0c51196f-a22c-46fb-b2d0-56f63d968610", "topic": "Time, timetables and money", "question_text": "A rehearsal runs from 22:40 until 00:15 the next day. Which duration and explanation are correct?", "option_a": "23 h 35 min; because it crosses midnight", "option_b": "35 min; subtract 40 from 15", "option_c": "1 h 35 min; 1 h 20 min to midnight, then 15 min more", "option_d": "2 h 35 min; count to 01:15", "correct_answer": "C", "explanation": "22:40 to 24:00 takes 1 h 20 min; add another 15 min after midnight to get 1 h 35 min."}, {"id": "10df6de9-9dcd-4d2a-8157-2131024063e7", "topic": "Time, timetables and money", "question_text": "Buses are scheduled for 08:15 and 08:50. Ada arrives at 08:28. Which next bus can she catch, and how long will she wait?", "option_a": "08:50 bus; wait 12 minutes", "option_b": "08:50 bus; wait 22 minutes", "option_c": "08:15 bus; wait 22 minutes", "option_d": "08:15 bus; wait 13 minutes", "correct_answer": "B", "explanation": "The 08:15 bus has left. From 08:28 to 08:50 is 22 minutes."}, {"id": "1ca18e27-5f9e-499d-ab33-571010aac1cb", "topic": "Time, timetables and money", "question_text": "Three notebooks cost £2.40 each. A pack of three costs £6.60. How much would you save by choosing the pack?", "option_a": "£1.20", "option_b": "£0.60", "option_c": "£0.40", "option_d": "£0.80", "correct_answer": "B", "explanation": "Individual total £7.20; 7.20 − 6.60 = £0.60."}, {"id": "539e32c9-b047-4819-94e4-ff6f1625e24c", "topic": "Time, timetables and money", "question_text": "Which listed time is in the afternoon, and why?", "option_a": "Both; both are afternoon times", "option_b": "14:20; it is 2:20 p.m.", "option_c": "Neither; both are morning times", "option_d": "08:20; it is 8:20 p.m.", "correct_answer": "B", "explanation": "14:20 is 2:20 p.m., after midday; 08:20 is in the morning."}, {"id": "620fcf34-59f0-4178-98c9-196b8fea30ad", "topic": "Time, timetables and money", "question_text": "The clock shows quarter past seven. What fraction of a complete clockwise turn has the minute hand made since 12?", "option_a": "1/2 of a full turn", "option_b": "1/12 of a full turn", "option_c": "1/4 of a full turn", "option_d": "3/4 of a full turn", "correct_answer": "C", "explanation": "The minute hand points to 3. From 12 to 3 is 90 degrees, or a quarter-turn."}, {"id": "ae737dc8-e10e-4af6-8a07-88b20b8a0de1", "topic": "Time, timetables and money", "question_text": "How many days are in April?", "option_a": "30", "option_b": "28", "option_c": "31", "option_d": "29", "correct_answer": "A", "explanation": "April has 30 days."}, {"id": "bfe2774a-c654-41f3-932f-46f415b6fe70", "topic": "Time, timetables and money", "question_text": "A train departs at 13:45 and is scheduled to arrive at 15:10. An additional 20-minute delay is announced. Which arrival time and total journey duration are correct?", "option_a": "15:30; the delayed journey lasts 1 h 45 min", "option_b": "15:10; the delayed journey lasts 1 h 25 min", "option_c": "15:20; the delayed journey lasts 1 h 35 min", "option_d": "15:30; the delayed journey lasts 1 h 25 min", "correct_answer": "A", "explanation": "Scheduled duration is 1 h 25 min; the delay adds 20 min."}, {"id": "cae9f13c-be4c-422b-a76f-36ebc06c945e", "topic": "Time, timetables and money", "question_text": "Refer to the bus timetable. Amina boards at Oak Street at 14:18. When will she arrive at the Market?", "option_a": "14:25", "option_b": "14:18", "option_c": "14:32", "option_d": "14:45", "correct_answer": "C", "explanation": "Read across the row for the later bus."}, {"id": "d5b9d426-4cf8-4b79-b4cc-27236a096465", "topic": "Time, timetables and money", "question_text": "You pay £5.00 for a £3.65 item. How much change should you receive?", "option_a": "£0.35", "option_b": "£1.65", "option_c": "£2.35", "option_d": "£1.35", "correct_answer": "D", "explanation": "£5.00 − £3.65 = £1.35."}, {"id": "d9020100-f300-4bb3-a143-cffbe5379db6", "topic": "Time, timetables and money", "question_text": "A museum charges £7.50 per adult and £4.25 per child. What is the total for one adult and two children?", "option_a": "£19.25", "option_b": "£15.75", "option_c": "£11.75", "option_d": "£16.00", "correct_answer": "D", "explanation": "£7.50 + 2 × £4.25 = £16.00."}]$original$::jsonb;
