 from jsonb_to_recordset(payload) as x(class_level text,curriculum text,topic text,topic_area text,topic_sublevel text,difficulty int,question_text text,option_a text,option_b text,option_c text,option_d text,correct_answer text,explanation text,numeric_answer numeric,question_image_url text,source_type text,source_name text,source_page text,ai_generated boolean,ai_prompt text,is_active boolean)
 where x.ai_prompt::jsonb->>'review_decision'<>'Retained';
